package br.com.catalogo;
import javax.swing.*;import java.awt.*;import java.nio.file.*;
final class LibraryPicker {
 static LibrarySettings.Profile choose(Component owner,LibrarySettings.Profile current)throws Exception{
  var state=LibrarySettings.read();var initial=current!=null?current:state.active()!=null?state.active():LibrarySettings.legacy();var directory=new JTextField(initial.directory().toString(),36);var database=new JTextField(initial.database());var known=new JComboBox<LibrarySettings.Profile>();for(var profile:state.profiles())known.addItem(profile);known.setSelectedItem(current);known.addActionListener(e->{var profile=(LibrarySettings.Profile)known.getSelectedItem();if(profile!=null){directory.setText(profile.directory().toString());database.setText(profile.database());}});
  var panel=new JPanel(new GridBagLayout());var browse=new JButton("Escolher pasta…");var chooseBank=new JButton("Escolher banco existente…");var folderRow=new JPanel(new BorderLayout(8,0));folderRow.add(directory);folderRow.add(browse,BorderLayout.EAST);var bankRow=new JPanel(new BorderLayout(8,0));bankRow.add(database);bankRow.add(chooseBank,BorderLayout.EAST);
  add(panel,0,"Bibliotecas usadas",known);add(panel,1,"Diretório dos livros digitais",folderRow);add(panel,2,"Nome do arquivo do banco",bankRow);add(panel,3,"",new JLabel("Cada pasta e banco formam uma biblioteca. Trocar não move os arquivos."));
  browse.addActionListener(e->{var chooser=new JFileChooser(directory.getText());chooser.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);if(chooser.showOpenDialog(owner)==JFileChooser.APPROVE_OPTION)directory.setText(chooser.getSelectedFile().toString());});chooseBank.addActionListener(e->{var chooser=new JFileChooser(directory.getText());chooser.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("Bancos SQLite","sqlite","sqlite3","db"));if(chooser.showOpenDialog(owner)==JFileChooser.APPROVE_OPTION){directory.setText(chooser.getSelectedFile().getParent());database.setText(chooser.getSelectedFile().getName());}});
  while(JOptionPane.showConfirmDialog(owner,panel,current==null?"Configure sua biblioteca":"Trocar biblioteca / banco",JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE)==JOptionPane.OK_OPTION)try{Path root=Path.of(directory.getText().strip());if(directory.getText().isBlank()||Files.exists(root)&&!Files.isDirectory(root))throw new IllegalArgumentException("Escolha um diretório válido para os livros digitais.");return new LibrarySettings.Profile(root,database.getText().strip());}catch(IllegalArgumentException e){JOptionPane.showMessageDialog(owner,e.getMessage(),"Biblioteca inválida",JOptionPane.ERROR_MESSAGE);}return null;
 }
 private static void add(JPanel panel,int row,String label,JComponent input){var box=new JPanel(new BorderLayout(0,5));if(!label.isBlank())box.add(new JLabel(label),BorderLayout.NORTH);box.add(input);var c=new GridBagConstraints();c.gridx=0;c.gridy=row;c.weightx=1;c.fill=GridBagConstraints.HORIZONTAL;c.insets=new Insets(0,0,14,0);panel.add(box,c);}
}
